# ── ПОРЯДОК ЗДЕСЬ ЗНАЧИМ: env-файл читается ДО любого нашего импорта ──
#
# `database`, `auth`, `crypto` и `zepp_client` читают окружение НА УРОВНЕ
# МОДУЛЯ (`DB_PATH`, `SECRET_KEY`, `CREDENTIALS_ENCRYPTION_KEY`,
# `ZEPP_TRACE`) — то есть в момент импорта. Стоял `load_dotenv()` ниже
# импортов, и всё это читалось из ГОЛОГО окружения процесса, мимо файла.
#
# Отказ немой и выглядит как работающая настройка: `os.getenv("DB_PATH")`
# после `load_dotenv()` отдаёт значение из файла, а `database.DB_PATH`
# держит умолчание. Стенд, настроенный env-файлом, молча заводит ВТОРУЮ
# базу рядом с собой и выглядит поднятым — на этом уже получен ложный
# замер (вход «не проходил», потому что аккаунта в той базе не было).
#
# Замер до правки, четыре настройки положены в env-файл: разошлись ТРИ —
# `DB_PATH` (./app.db вместо заданного), `SECRET_KEY` (умолчание вместо
# заданного, то есть подписи токенов шли не тем ключом) и `ZEPP_TRACE`.
# Сошёлся один `CREDENTIALS_ENCRYPTION_KEY`, и только потому, что `crypto`
# импортируется не здесь, а внутри функции — то есть уже после.
#
# Проба живёт в репозитории и читается по коду возврата: `py check_env_order.py`.
