# ══════════════════════════════════════════════════════════════════════════════
# ГЕЙТ ПОДТВЕРЖДЁННОЙ ПОЧТЫ — ОДНО МЕСТО НА ВСЕ ЭНДПОИНТЫ ЗАПИСИ (BACKLOG №24)
# ══════════════════════════════════════════════════════════════════════════════
# Почему middleware, а не зависимость в каждом обработчике. Зависимость,
# которую надо не забыть дописать, — это гарантия, что следующий добавленный
# эндпоинт её не получит, и никто этого не заметит: отказа нет, ошибки нет,
# запись просто проходит. Ровно так и вышло: гейт `_verification_gate` стоял
# на ЧЕТЫРЁХ страницах инструментов и ни на одном из 59 эндпоинтов записи —
# то есть закрывал вход в комнату, оставив открытыми все окна.
#
# Middleware видит КАЖДЫЙ запрос, включая маршруты, зарегистрированные мимо
# декоратора (`@app.api_route`, `include_router`) — а таких в приложении пять,
# и грепом по `@app.post` они не находятся вовсе (см. check_endpoints.py).
# Новый эндпоинт получает проверку в момент появления, не делая ничего.
#
# ГРАНИЦА: гейт закрывает только методы, которые меняют состояние. Чтение
# непроверенному аккаунту оставлено намеренно — он должен видеть, куда попал,
# и что именно ему предлагают подтвердить; страницы инструментов и так
# закрыты плашкой `_verification_gate`.

# Методы, которые меняют состояние. GET сюда не входит: единственный
# пишущий GET (`/verify/{token}`) — это само подтверждение почты.
ГЕЙТ_МЕТОДЫ = {"POST", "PUT", "PATCH", "DELETE"}

# ЭНДПОИНТЫ, КОТОРЫМ ГЕЙТ СТАВИТЬ НЕЛЬЗЯ. Список — исключения с причиной,
# а не «всё, что не подошло». Закрыть любой из них значит запереть аккаунт
# насмерть: подтвердить почту станет нечем.
#
# Тот же список читает `check_endpoints.py` — импортом отсюда, а не копией.
# Вторая копия разошлась бы с первой молча, и опись начала бы утверждать,
# что эндпоинт закрыт, когда он открыт.
ГЕЙТ_ИСКЛЮЧЕНИЯ_ТОЧНО = {
    "/login",                    # вход: сессии до него нет вовсе
    "/register",                 # регистрация: аккаунта ещё нет
    "/logout",                   # выход обязан работать всегда
    "/forgot-password",          # восстановление пароля: сессии нет
    "/verify-pending/resend",    # повторное письмо незалогиненному
    "/resend-verification",      # повторное письмо залогиненному, но неподтверждённому
    "/api/delete-account",       # запирать человека внутри аккаунта нельзя
    "/deploy-hook",              # служебный вебхук, защищён секретом в заголовке
    "/api/agent/slots/check",    # внешний агент по ключу, не пользователь
}
# Префиксы — для маршрутов с параметром в пути: в middleware приходит
# фактический путь (`/verify/abc123`), а не шаблон (`/verify/{token}`).
ГЕЙТ_ИСКЛЮЧЕНИЯ_ПРЕФИКС = (
    "/verify/",           # ПОДТВЕРЖДЕНИЕ ПОЧТЫ — действие, снимающее гейт
    "/reset-password/",   # восстановление пароля по ссылке из письма
    "/static/",
)

# 428 Precondition Required (RFC 6585 §3), а не 401 и не 403, и это выбор,
# а не вкус. 401 означает «представьтесь» — человек представился, сессия
# рабочая. 403 означает «вам нельзя» — читается как бан, и пользователь
# идёт писать в поддержку вместо того, чтобы открыть почту. 428 означает
# ровно то, что происходит: доступ откроется, как только будет выполнено
# названное условие. Заодно клиент отличает этот случай от прочих по коду,
# не разбирая тело.
ГЕЙТ_КОД = 428


def _гейт_путь_исключён(путь: str) -> bool:
    return (путь in ГЕЙТ_ИСКЛЮЧЕНИЯ_ТОЧНО
            or путь.startswith(ГЕЙТ_ИСКЛЮЧЕНИЯ_ПРЕФИКС))


@app.middleware("http")
async def гейт_подтверждения_почты(request: Request, call_next):
    """Непроверенный аккаунт ничего не записывает. Один заслон на всё."""
    if request.method not in ГЕЙТ_МЕТОДЫ or _гейт_путь_исключён(request.url.path):
        return await call_next(request)

    user_id = decode_token_user_id(request.cookies.get("access_token", ""))
    if user_id is None:
        # Сессии нет. Это не наша забота: обработчик сам решит, требуется
        # ли ему аутентификация. Подменять здесь 401 на 428 значило бы
        # сообщать анониму о состоянии чужой почты.
        return await call_next(request)

    db = SessionLocal()
    try:
        u = db.query(User).filter(User.id == user_id).first()
        # `is False`, а не `not ...`: у старых аккаунтов поле NULL, и они
        # не блокируются — ровно как в `_verification_gate`. Единственное
        # место, где эти два заслона обязаны совпадать по смыслу.
        непроверенный = bool(u) and u.is_verified is False
    finally:
        db.close()

    if not непроверенный:
        return await call_next(request)

    print(f"[verify-gate] {request.method} {request.url.path} — почта не подтверждена")
    # Форма ответа по тому, что запрашивали. Форме `Accept: text/html`
    # отдаём страницу-плашку: JSON в адресной строке браузера человек
    # прочитать не сможет, а действий у него ровно два — открыть почту
    # или запросить письмо заново.
    принимает = request.headers.get("accept", "")
    if "text/html" in принимает and "application/json" not in принимает:
        return RedirectResponse("/verify-pending", status_code=303)
    return JSONResponse(
        {"error": "Подтвердите почту — на неё отправлено письмо со ссылкой. "
                  "Пока она не подтверждена, сохранять данные нельзя.",
         "code": "email_not_verified"},
        status_code=ГЕЙТ_КОД)


@app.middleware("http")
async def log_request(request: Request, call_next):
    """Одна строка на каждый запрос: откуда, что, сколько миллисекунд, чем кончилось.

    Появилось после разбора сбоя 6 августа. Тогда вебхуки голосового агента
    четыре раза подряд получили «connection reset by peer», а доказать, что
    приложение здорово, удалось только по метрикам Prometheus и гистограмме
    времени ответа — на что ушло три часа. Причина: uvicorn пишет факт ответа,
    но не пишет НИ длительность, НИ идентификатор запроса Fly, ни адрес
    клиента. Сопоставить свою запись с чужим журналом было нечем.

    `Fly-Request-Id` — тот же идентификатор, что Fly отдаёт клиенту
    в заголовке ответа. По нему запрос сшивается с журналом принимающей
    стороны в одну строку, без гадания по секундам.

    `/static/` пропускаем: браузер тянет оттуда десяток файлов на страницу,
    и полезные строки утонули бы среди них.

    Строку в лог не пишем, а Cache-Control — ставим: `StaticFiles` своего
    не отдаёт, и без этого заголовка браузер берёт эвристику и на сервер
    не ходит вовсе (задача 77, разбор у `_кеш_статики`).
    """
    if request.url.path.startswith("/static/"):
        ответ = await call_next(request)
        ответ.headers["Cache-Control"] = _кеш_статики(
            request.url.path, request.query_params.get("v", ""))
        return ответ

    старт = time.perf_counter()
    метка = datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")
    путь = request.url.path + (f"?{request.url.query}" if request.url.query else "")
    ip = (request.headers.get("Fly-Client-IP")
          or request.headers.get("X-Forwarded-For", "").split(",")[0].strip()
          or (request.client.host if request.client else "—"))
    rid = request.headers.get("Fly-Request-Id", "—")
    ua = (request.headers.get("User-Agent", "—") or "—")[:60]
    proto = f"HTTP/{request.scope.get('http_version', '?')}"

    def строка(итог: str, мс: float) -> str:
        return (f"[req] {метка}Z {request.method} {путь} {итог} {мс:.0f}ms "
                f"ip={ip} rid={rid} {proto} ua={ua!r}")

    try:
        ответ = await call_next(request)
    except Exception as e:
        # Не глушим: печатаем и пробрасываем дальше. Проглоченное здесь
        # исключение превратило бы 500 в запрос без единого следа —
        # ровно та немота, из-за которой этот middleware и появился.
        print(строка(f"ИСКЛЮЧЕНИЕ {type(e).__name__}: {e}",
                     (time.perf_counter() - старт) * 1000), flush=True)
        raise

    print(строка(str(ответ.status_code), (time.perf_counter() - старт) * 1000),
          flush=True)

    # Страница обязана переспрашиваться. Без этого версия в адресе статики
    # (задача 77) дырявая: браузер отдал бы из кеша СТАРУЮ разметку, в ней
    # стоит старый `?v=`, а тот помечен `immutable` — то есть починенный CSS
    # не приехал бы вообще ни по какому пути. Замер 2026-08-14: HTML уходил
    # без Cache-Control и без единого валидатора — ни etag, ни last-modified.
    # Именно `no-cache`, а не `no-store`: страницу можно держать в кеше,
    # нельзя брать оттуда без вопроса. `no-store` заодно выключил бы
    # восстановление из bfcache в Firefox.
    if ответ.headers.get("content-type", "").startswith("text/html"):
        ответ.headers.setdefault("Cache-Control", "no-cache")
    return ответ


def _plural_ru(n: int, one: str, few: str, many: str) -> str:
    """Русское склонение существительного по числу. Пример: _plural_ru(21, 'упражнение', 'упражнения', 'упражнений') -> 'упражнение'."""
    n = abs(n)
    if 11 <= n % 100 <= 14:
        return many
    if n % 10 == 1:
        return one
    if 2 <= n % 10 <= 4:
        return few
    return many

OPENROUTER_API_KEY  = os.getenv("OPENROUTER_API_KEY", "")
MODEL               = os.getenv("MODEL",         "anthropic/claude-haiku-4-5")
LETTER_MODEL        = os.getenv("LETTER_MODEL",  "anthropic/claude-opus-4-5")   # генерация письма
ANALYZE_MODEL       = os.getenv("ANALYZE_MODEL", "anthropic/claude-sonnet-4-5") # анализ вакансии (JSON)
PARSER_MODEL        = os.getenv("PARSER_MODEL",  "anthropic/claude-sonnet-4-5") # парсер резюме (JSON)
# ── Потолки ответа модели ─────────────────────────────────────────────────────
# Все до единого — здесь и с именем. Число на месте вызова невидимо: его нельзя
# ни грепнуть, ни сверить с фактическим расходом, ни поднять из окружения.
# Ровно так /api/analyze-vacancy остался с захардкоженными 700 при фактическом
# расходе 958 — таблица в CLAUDE.md утверждала, что лимит поднят, а кнопка
# падала «Unterminated string» примерно на трети вакансий.
#
# max_tokens — потолок, а не резерв: платим за фактически сгенерированное,
# поэтому берём с запасом. Экономия здесь ничего не стоит и покупает обрыв.
# Фактический расход по каждому — замеры в CLAUDE.md §2.1, таблица потолков;
# в лог он пишется всегда (см. _model_output), так что запас проверяем не
# рассуждением, а строкой `finish=… токенов=N из M`.
ANALYZE_MAX_TOKENS  = int(os.getenv("ANALYZE_MAX_TOKENS",  "2000"))  # анализ вакансии, JSON из 9 полей
LETTER_MAX_TOKENS   = int(os.getenv("LETTER_MAX_TOKENS",   "3000"))  # сопроводительное письмо, 200-450 слов
PARSER_MAX_TOKENS   = int(os.getenv("PARSER_MAX_TOKENS",   "4000"))  # резюме → досье, JSON со всем опытом
PROGRAM_MAX_TOKENS  = int(os.getenv("PROGRAM_MAX_TOKENS",  "6000"))  # программа тренировок, JSON на 3-6 дней
CHAT_MAX_TOKENS     = int(os.getenv("CHAT_MAX_TOKENS",     "1000"))  # реплика ассистента (дневник, тренер)
VISION_MAX_TOKENS   = int(os.getenv("VISION_MAX_TOKENS",   "800"))   # разбор фото еды
# ПОТОЛОК РАЗМЕРА КАРТИНКИ, уходящей в модель. Не наша выдумка: Anthropic
# принимает не больше 5 МБ на изображение, и картинка сверх этого —
# гарантированный отказ, а не «может, повезёт». Проверяется в ОДНОМ месте
# (`_call_vision`), через которое идут все четыре точки разбора фото:
# на месте вызова число нельзя ни грепнуть, ни сверить с расходом (§2.1)
VISION_IMAGE_MAX_MB = float(os.getenv("VISION_IMAGE_MAX_MB", "5"))
# ПОТОЛОК ЗАГРУЗКИ СНИМКА. У загрузки картинки Enshrouded такой потолок
# был с самого начала (`ENS_MAX_UPLOAD`), у разбора фото — не было
# ни одного: эндпоинт принимал сколько угодно байт. Взят с запасом —
# после уменьшения на клиенте снимок весит ~0.5 МБ, а без него самый
# тяжёлый случай (108 Мпикс) это 10 МБ; 20 МБ не отвергнут ни одну
# настоящую фотографию и закрывают приём произвольного объёма
PHOTO_MAX_UPLOAD_MB = float(os.getenv("PHOTO_MAX_UPLOAD_MB", "20"))
FOOD_MAX_TOKENS     = int(os.getenv("FOOD_MAX_TOKENS",     "300"))   # КБЖУ одного продукта, JSON из 5 чисел
TRANSLATE_MAX_TOKENS = int(os.getenv("TRANSLATE_MAX_TOKENS", "200"))  # перевод слов запроса, JSON из пар
MEDKIT_MAX_TOKENS   = int(os.getenv("MEDKIT_MAX_TOKENS",   "900"))   # карточка аптечки, JSON из 8 полей плюс вопрос

# ── ПОЛИТИКА ДАННЫХ OPENROUTER — ОДНО МЕСТО НА ВСЕ ВЫЗОВЫ ────────────────────
#
# BACKLOG №19. Промпты этого приложения — резюме, вакансии, дневник питания,
# переписка с ассистентом и тренером. Это персональные данные и данные
# о здоровье, и политика конфиденциальности обещает, что мы их не раздаём.
# По умолчанию OpenRouter волен маршрутизировать запрос к провайдеру,
# который вправе сохранять содержимое и обучаться на нём.
#
# ЧТО ЗДЕСЬ ОБЪЯВЛЕНО (имена полей сверены с живой документацией
# openrouter.ai/docs/features/provider-routing, а не по памяти):
#
#   data_collection: "deny" — не маршрутизировать к провайдеру, который
#                             вправе хранить содержимое запроса
#   zdr: true               — только эндпоинты с политикой нулевого
#                             удержания данных
#
# ПОЧЕМУ ОДНОЙ КОНСТАНТОЙ, А НЕ СЛОВАРЁМ НА МЕСТЕ ВЫЗОВА. Точек вызова
# chat/completions в этом файле ДЕСЯТЬ, и общей обёртки у запроса нет:
# `_model_output` разбирает ОТВЕТ, а тело каждый раз собирается заново.
# Настройка, вписанная в одно тело, не доезжает до остальных девяти —
# и не доехала бы молча, ровно как `max_tokens: 700` не доехал до второго
# места анализа вакансии (§2.1). Поэтому политика объявлена один раз,
# подставляется распаковкой `**ПОЛИТИКА_ЗАПРОСА`, а полноту охвата
# сторожит тест `tests/test_openrouter_policy.py`: он находит все вызовы
# chat/completions обходом файла и требует распаковку у каждого.
#
# ЗАМЕР 2026-08-20, живыми вызовами по всем десяти местам: ответили все
# десять и до, и после. Маршрут при этом РЕАЛЬНО меняется — opus-4-8 без
# запрета уходил на «Claude Platform on AWS», с запретом на «Google».
# Отрицательный контроль: `dots-studio/dots-3-note-preview:free` без
# запрета отвечает (AtlasCloud), с запретом даёт HTTP 404 «No endpoints
# found matching your data policy (Zero data retention)». То есть запрет —
# факт, а не слово.
#
# ЧЕГО ЭТО НЕ ЗАКРЫВАЕТ — РАСПОЗНАВАНИЕ РЕЧИ. Эндпоинт
# /api/v1/audio/transcriptions поле `provider` ИГНОРИРУЕТ: замер показал
# HTTP 200 и с `zdr: true`, и с заведомо несуществующим именем провайдера
# (`only: ["несуществующий-провайдер"]`). Тело при этом читается —
# подложенное имя модели даёт HTTP 400. Значит, подставить туда политику
# нельзя: поле молча не действует, а поле, которое выглядит защитой
# и ею не является, хуже отсутствующего. Голосовой ввод дневника закрыть
# можно только настройкой АККАУНТА (openrouter.ai/settings/privacy,
# группа «Non-frontier» / guardrails), и это вне кода — BACKLOG №19.
#
# Переменными окружения, а не литералами: ветку «политика снята» иначе
# нечем прогнать, а проверка, которую нечем прогнать, означает
# «проверено рассуждением» (§6.0.1).
OR_DATA_COLLECTION = os.getenv("OR_DATA_COLLECTION", "deny")   # deny | allow
OR_ZDR = os.getenv("OR_ZDR", "1").strip().lower() not in ("0", "false", "no", "")
ПОЛИТИКА_ЗАПРОСА = {"provider": {"data_collection": OR_DATA_COLLECTION,
                                 "zdr": OR_ZDR}}

# АДРЕС OPENROUTER — ПЕРЕМЕННОЙ, а не строкой на месте вызова. Причина
# та же, что у TURNSTILE_VERIFY_URL и RESEND_API_URL: ветку «сервис
# не ответил / ответил не тем» иначе нечем прогнать, а проверка,
# которую нечем прогнать, означает «проверено рассуждением» (§6.0.1).
# Замер 2026-08-21 по задаче 128 упирался ровно в это: сообщение
# «Ответ ассистента оборвался» показывалось и тогда, когда ответа
# не было вовсе, — и убедиться в этом можно было, только подставив
# адрес, который отвечает не так, как OpenRouter.
#
# Адресов ДВА, и второй не выводится из первого подстановкой: у речи
