def _кеш_статики(путь: str, версия: str) -> str:
    """Заголовок Cache-Control для запроса статики. Три случая, а не два.

    Правило одно: **вечно кешируется только адрес, который называет своё
    содержимое.** Всё остальное браузер обязан переспросить.

    | Запрос | Заголовок | Почему |
    |---|---|---|
    | `?v=` совпал с текущим хешем | `immutable`, год | содержимое по этому адресу больше не изменится по построению |
    | `.css`/`.js` без версии или с чужой | `no-cache` | это страховка: файл, который забыли пометить версией, не должен молча замерзать на год. Тело при этом остаётся в кеше — `etag` даёт 304, а не повторную выкачку |
    | прочее (картинки, svg) | сутки | их правят заменой файла, а не редактированием; окно в сутки дешевле, чем ревалидация 1746 картинок упражнений на каждой открытой странице |

    Чужая версия в адресе отдаёт ТЕКУЩЕЕ содержимое (StaticFiles на
    query не смотрит) и `no-cache` — то есть старый адрес не подменяет
    новый, а сам себя обесценивает.
    """
    имя = путь[len("/static/"):]
    if версия and версия == версия_статики(имя):
        return f"max-age={СТАТИКА_ГОД}, immutable"
    if имя.endswith((".css", ".js")):
        return "no-cache"
    return f"max-age={СТАТИКА_СУТКИ}"


def user_has_access(user: User, tool_id: str, db: Session) -> bool:
    if user.is_admin:
        return True
    return db.query(ToolAccess).filter(
        ToolAccess.user_id == user.id,
        ToolAccess.tool_id == tool_id
    ).first() is not None


def _safe_next(next_url: str) -> str:
    """Куда вернуть человека после входа. Только внутренний путь сайта.

    Внешние адреса и протокол-относительные («//чужой.сайт») отбрасываются:
    иначе форма входа становится открытым редиректом, которым удобно
    маскировать фишинговые ссылки под наш домен.
    """
    if not next_url or not next_url.startswith("/") or next_url.startswith("//"):
        return "/"
    return next_url


def _tool_preview(request: Request, tool_id: str):
    """Витрина инструмента для неавторизованных — вместо редиректа на /login.

    Раньше ссылка на инструмент вела в тупик: человек попадал на голую форму
    входа, не понимая, куда пришёл, а роботы превью считывали мета-теги формы
    вместо описания инструмента — в Telegram карточка /hh называлась «Вход».

    Роботам и людям отдаётся одно и то же. Развилка по User-Agent была бы
    клоакингом: поисковик индексирует одно, человек видит другое — расхождение
    ровно того типа, за которое понижают в выдаче.
    """
    tool = next((t for t in TOOLS if t["id"] == tool_id), None)
    if not tool:
        return RedirectResponse("/login", status_code=302)
    return templates.TemplateResponse(
        request=request, name="tool_preview.html",
        context={"tool": tool,
                 "icon": TOOL_ICONS.get(tool_id, "box"),
                 "eyebrow": TOOL_EYEBROWS.get(tool_id, "Инструмент")})


def _verification_gate(request: Request, user: User, tool_name: str, db: Session = None):
    """Плашка "подтвердите email" вместо инструмента, если is_verified явно False.
    None (is_verified не заполнен у старых аккаунтов) — не блокирует.

    db нужен, чтобы состояние кнопки совпадало с состоянием сервера: если письмо
    только что отправляли, кнопка приходит уже выключенной с отсчётом, а не
    предлагает действие, которое гарантированно упрётся в отказ."""
    if user.is_verified is False:
        return templates.TemplateResponse(request=request, name="verify_required.html",
                                          context={"user": user, "tool_name": tool_name,
                                                   "cooldown": _email_cooldown_left(db, user.id) if db else 0})
    return None


async def _verify_turnstile(token: str, remote_ip: str = None) -> bool:
    """Проверка Cloudflare Turnstile через siteverify. Если TURNSTILE_SECRET_KEY
    не задан (ключи ещё не выданы) — не блокируем регистрацию."""
    if not TURNSTILE_SECRET_KEY:
        return True
    if not token:
        return False
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            data = {"secret": TURNSTILE_SECRET_KEY, "response": token}
            if remote_ip:
                data["remoteip"] = remote_ip
            r = await client.post(TURNSTILE_VERIFY_URL, data=data)
            return bool(r.json().get("success"))
    except Exception:
        return False  # ошибка проверки — блокируем, а не пропускаем молча


async def _turnstile_check(token: str, remote_ip: str = None) -> tuple[bool, bool, str]:
    """Как _verify_turnstile, но различает «проверку не прошли» и «проверить не смогли».

    Возвращает (прошла, доступен_ли_cloudflare, причина). На форме входа это
    различие принципиально и реализовано ДВУМЯ разными ветками (задача 22):

      · Cloudflare сказал «нет» — отказываем. Это ответ, и он однозначен;
      · Cloudflare не ответил — пропускаем. Это НАША проблема, а не
        пользователя: падение стороннего сервиса не должно закрывать вход
        владельцу собственной админки.

    Третьим значением идёт причина недоступности — она уезжает в лог. Без
    неё «Cloudflare недоступен» неотличимо от «Cloudflare вернул 403,
    потому что мы протухли ключом», и fail-open по недоступности тихо
    выродится в fail-open по всему.
    """
    if not TURNSTILE_SECRET_KEY:
        return True, True, "ключ не задан"
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            data = {"secret": TURNSTILE_SECRET_KEY, "response": token}
            if remote_ip:
                data["remoteip"] = remote_ip
            r = await client.post(TURNSTILE_VERIFY_URL, data=data)
        if r.status_code != 200:
            return False, False, f"siteverify ответил HTTP {r.status_code}"
        return bool(r.json().get("success")), True, ""
    except httpx.HTTPError as e:
        return False, False, f"{type(e).__name__}: {str(e)[:120]}"
    except ValueError as e:
        return False, False, f"ответ не разобрался: {type(e).__name__}: {str(e)[:120]}"


# ── Защита формы входа от перебора ────────────────────────────────────────────
# ПОЛНОЙ БЛОКИРОВКИ АККАУНТА НЕТ НИ В КАКОМ ВИДЕ, даже временной. Любой, кто
# знает чужой адрес, держал бы этим чужой вход запертым — это не защита, это
# оружие против пользователя. Адрес знают как минимум он сам и его почтовый
# провайдер, так что «знает адрес» — не редкость.
#
# Ключа два, и последствия у них РАЗНЫЕ (BACKLOG.md, задача 22):
#
#   по адресу подключения — задержка ответа и потолок числа попыток;
#   по введённому адресу почты — задержка ответа и письмо владельцу.
#
# Считать только по адресу подключения нельзя: за одним адресом сидит целый
# NAT мобильного оператора, и порог рубит всех, кто за ним. Считать только
# по аккаунту нельзя тем более — см. первый абзац.

LOGIN_WINDOW_SEC     = 15 * 60   # скользящее окно учёта неудач
LOGIN_CAPTCHA_AFTER  = 3         # с этой неудачи требуем Turnstile
LOGIN_BLOCK_AFTER    = 30        # с этой неудачи ПО АДРЕСУ ПОДКЛЮЧЕНИЯ отказываем
RATELIMIT_OFF_FILE   = "/data/ratelimit_off"   # аварийный выход, см. BACKLOG №1

# ПОЧЕМУ ПОТОЛОК ЧИСЛА ПОПЫТОК ОСТАЛСЯ, хотя «по IP — только задержка».
# Замер 2026-08-18 на живом приложении: 30 запросов, отправленных
# ОДНОВРЕМЕННО с одного адреса при задержке, разогнанной до потолка 4 с,
# заняли 6.70 с — при том, что последовательно те же запросы заняли бы
# 146.5 с. Задержка сделана через `await asyncio.sleep`, и параллельные
# запросы ждут её параллельно: пропускную способность перебора она
# не ограничивает вовсе. Ограничивает её только счёт попыток.
#
# Порог поднят с 15 до 30 ровно потому, что рядом появился второй ключ:
# перебор конкретного аккаунта теперь тормозится сам по себе, и потолку
# по адресу можно быть менее резким к тем, кто сидит за общим NAT. Окно
# скользящее — адрес освобождается сам, «разблокировать» его не нужно.

# Письмо владельцу: сколько неудач по ОДНОМУ аккаунту и как часто писать.
# Десять — заведомо больше, чем опечатки живого человека (замер по своим
# заходам: три-четыре подряд при смене раскладки), и заведомо меньше, чем
# перебор. Шесть часов — чтобы за сутки пришло не больше четырёх писем:
# письмо должно приходить не чаще, чем человек успевает на него
# отреагировать, иначе оно превращается в шум, который перестают читать.
NOTICE_AFTER         = 10
NOTICE_COOLDOWN_SEC  = 6 * 3600

# Запросы сброса пароля с одного адреса подключения
FORGOT_WINDOW_SEC = 15 * 60
FORGOT_MAX_PER_IP = 5

# Письма на ОДИН адрес назначения, независимо от того, каким эндпоинтом их
# вызвали и есть ли кука. Восемь за сутки: живому человеку, у которого всё
# идёт плохо, нужно письмо подтверждения, два повтора, сброс пароля и ещё
# один повтор — это пять. Восемь оставляют запас; всё, что выше, — рассылка
# в чужой ящик нашими руками.
MAIL_WINDOW_SEC   = 24 * 3600
MAIL_MAX_PER_ADDR = 8

# Сколько держим строки журнала. Считается из окон, а не вписывается числом:
# заведи кто-нибудь окно длиннее срока хранения — и счёт молча начал бы
# терять попытки, которые обязан считать. Отказ был бы немой: лимит просто
# перестал бы срабатывать.
#
# СРОК НАЗВАН ЕЩЁ В ОДНОМ МЕСТЕ — в политике конфиденциальности
# (STATIC_PAGES["privacy"], таблица «Сколько мы храним данные», строка
# «Журнал попыток входа»: сутки). Меняете окна так, что максимум перестаёт
# быть сутками, — правьте политику тем же коммитом, иначе она молча
# становится неправдой. Та же ловушка, что с retention снимков тома (§10).
ПОПЫТКИ_ХРАНИТЬ_SEC = max(LOGIN_WINDOW_SEC, FORGOT_WINDOW_SEC,
                          MAIL_WINDOW_SEC, NOTICE_COOLDOWN_SEC)


def _ratelimit_disabled(ip: str = None, где: str = "") -> bool:
    """Аварийный выход: `flyctl ssh console -C "touch /data/ratelimit_off"`.
    Файл лежит на volume и переживает рестарт, поэтому о каждом срабатывании
    сообщаем в лог — иначе защита останется выключенной тихо и навсегда.

    Пока файл лежит, режим заодно наблюдательный: печатаем определившийся IP,
    чтобы убедиться, что это реальный адрес посетителя, а не 172.16.x прокси
    Fly. Проверять это надо ДО включения лимитов, иначе один неудачный вход
    запер бы вход всем сразу."""
    if os.path.exists(RATELIMIT_OFF_FILE):
        print(f"[login] защита отключена файлом /data/ratelimit_off; "
              f"наблюдаемый IP: {ip or '—'} ({где})")
        return True
    return False


def _client_ip(request: Request) -> str:
    """Реальный IP посетителя.

    request.client.host здесь бесполезен: приложение стоит за прокси Fly и видит
    его внутренний адрес (проверено на проде — все запросы приходят с
    172.16.13.90, и мой из России, и внутренний health-check). Брать его значит
    считать всех посетителей одним адресом: первая же неудача заперла бы вход всем.

    Заголовкам можно доверять: приложение слушает внутренний порт и снаружи
    доступно только через прокси Fly, который эти заголовки перезаписывает.
    """
    fly = request.headers.get("fly-client-ip")
    if fly:
        return fly.strip()
    xff = request.headers.get("x-forwarded-for")
    if xff:
        return xff.split(",")[0].strip()
    return request.client.host if request.client else "unknown"


# Минимальная длительность ответа: выравнивает тайминг между «адрес найден»
# и «не найден», иначе разница во времени сама выдаёт, есть ли аккаунт
FORGOT_MIN_RESPONSE_SEC = 0.7


def _rate_key(ip: str) -> str:
    """Ключ, по которому ведётся счётчик неудач.

    Для IPv4 — сам адрес. Для IPv6 — префикс /64, потому что провайдер выдаёт
    клиенту не один адрес, а целую подсеть /64 (18 квинтиллионов адресов).
    Считая по полному адресу, мы ловили бы только того, кто сидит на одном
    IPv6 и не меняет его: любой, кто переключает адрес внутри своей подсети,
    обходил бы лимит бесплатно и бесконечно.

    Версия адреса определяется разбором через ipaddress, а не наличием
    двоеточия: заголовок может прийти с портом, в скобках или искажённым.
    """
    try:
        адрес = ipaddress.ip_address(ip)
    except ValueError:
        return ip                      # не разобрали — считаем по строке как есть
    if адрес.version == 6:
        return str(ipaddress.ip_network(f"{адрес}/64", strict=False))
    return str(адрес)


def _ключ_ip(ip: str) -> str:
    """Ключ журнала по адресу подключения."""
    return f"ip:{_rate_key(ip)}"


def _хеш_адреса(соль: str, адрес: str) -> str:
    """Ключ журнала по адресу почты.

    Хеш, а не сам адрес, и врать про причину не будем: адрес-кандидат
    проверяется по такому хешу за микросекунду, необратимости здесь нет.
    Смысл в другом — в журнал попадают ЧУЖИЕ ящики (опечатки, перебор
    по адресам, которых у нас вовсе нет), и накапливать их читаемым
    списком незачем. Соль разная у видов, чтобы по совпадению строк
    нельзя было связать «на этот адрес слали письма» и «этим адресом
    пробовали войти».
    """
    return hashlib.sha256(f"{соль}\x00{адрес.strip().lower()}".encode("utf-8")).hexdigest()[:32]


def _ключ_аккаунта(email: str) -> str:
    return f"acct:{_хеш_адреса('acct', email)}"


def _ключ_почты(email: str) -> str:
    return f"mail:{_хеш_адреса('mail', email)}"


def _попытки_убрать_старое(db) -> None:
    """Чистка журнала. ЛЕНИВАЯ — при каждой записи, не по расписанию.

    Почему так, а не задачей в cron. Задача по расписанию — это ещё одна
    внешняя штука, которую можно не завести, забыть включить или сломать
    молча; ровно на такой подпорке держался прежний счётчик, и она
    отвалилась. Чистка при записи не может отстать от записи по построению:
    нет записей — нечего и убирать, а строки старше окна не влияют ни
    на один счёт.

    Запись идёт только на НЕудачном входе и на отправке письма — то есть
    на редком пути. Индекс по created_at есть.
    """
    порог = datetime.utcnow() - timedelta(seconds=ПОПЫТКИ_ХРАНИТЬ_SEC)
    db.query(LoginAttempt).filter(LoginAttempt.created_at < порог).delete(
        synchronize_session=False)


def _записать_попытку(db, ключ: str, вид: str, исход: str) -> None:
    """Одна строка журнала плюс уборка старого. Коммитит сама."""
    db.add(LoginAttempt(ключ=ключ, вид=вид, исход=исход, created_at=datetime.utcnow()))
    _попытки_убрать_старое(db)
    db.commit()


def _попыток(db, ключ: str, вид: str, окно: int, исход: str = "fail") -> int:
    """Сколько событий по этому ключу внутри окна."""
    порог = datetime.utcnow() - timedelta(seconds=окно)
    return (db.query(LoginAttempt)
            .filter(LoginAttempt.ключ == ключ, LoginAttempt.вид == вид,
                    LoginAttempt.исход == исход, LoginAttempt.created_at > порог)
            .count())


def _сбросить_попытки(db, *ключи: str) -> None:
    """Удачный вход обнуляет счёт и адреса, и аккаунта: владелец доказал,
    что он владелец. Без этого человек, вошедший с четвёртой попытки,
    таскал бы за собой задержку ещё пятнадцать минут."""
    db.query(LoginAttempt).filter(LoginAttempt.ключ.in_(ключи),
                                  LoginAttempt.вид == "login").delete(
        synchronize_session=False)


async def _пауза(db, секунды: float) -> None:
    """Задержка ответа С ОСВОБОЖДЁННЫМ СОЕДИНЕНИЕМ. Не asyncio.sleep напрямую.

    ЗАМЕР 2026-08-18, из-за которого это отдельная функция. Пул соединений
    был QueuePool на 5 + 10 оверфлоу, ожидание 30 с, а обработчики
    объявлены `async` и работают с базой синхронно. Значит поток, ждущий
    свободное соединение, блокировал ВЕСЬ event loop.

    ОЧЕРЕДИ ПУЛА С 2026-08-20 НЕТ (`max_overflow=-1`, задача 105), и всё же
    функция остаётся обязательной. Причина сменилась, а не исчезла:
    соединение, занятое на четыре секунды сна, держит открытую транзакцию
    чтения — под WAL это мешает контрольной точке и растит файл журнала,
    а при откате журнала обратно вернуло бы и взаимную блокировку. Тридцать одновременных
    попыток входа: пятнадцать держат соединение и спят в `await`, остальные
    встают в очередь на пуле и стопорят цикл — спящие не просыпаются
    и соединения не отдают. Приложение зависает целиком: /health перестал
    отвечать вовсе, в журнале ни строки, ни исключения.

    Немой отказ в чистом виде: ни ошибки, ни трейсбека, просто тишина.
    До правки задачи 22 это спало латентно — на пути 429 и на пути капчи
    база вообще не трогалась, соединение не бралось, и одновременных
    держателей было единицы.

    `db.close()` возвращает соединение в пул. Сессия после этого рабочая:
    следующий запрос откроет соединение заново.
    """
    if секунды <= 0:
        return
    db.close()
    await asyncio.sleep(секунды)


async def _в_потоке(db, функция, *аргументы):
    """Блокирующий вызов в потоке С ОСВОБОЖДЁННЫМ СОЕДИНЕНИЕМ к базе.

    Родная сестра `_пауза`, и понадобилась ровно по той же причине —
    но обнаружилась она только ПОСЛЕ починки bcrypt, и это стоит записать.

    ЗАМЕР 2026-08-18. Один `asyncio.to_thread` без освобождения соединения
    убрал блокировку цикла на десяти входах (медиана `/health` 967 → 156 мс),
    а на тридцати сделал ХУЖЕ, чем было: 6.6 с превратились в 180 с.

    Механика. Пока bcrypt считал в цикле, запросы шли гуськом и держателей
    соединения было один-два. Перенос в поток сделал их по-настоящему
    одновременными — тридцать обработчиков разом держат соединение через
    `await`, а в пуле их было 5+10. Шестнадцатый вставал ждать пул, и ждал
    СИНХРОННО, то есть снова стоял весь цикл. Проверено подстановкой:
    с пулом 60+20 те же тридцать входов проходили за 1.97 с.

    Пул при этом не лечение, а перенос стены: соединение, занятое на время
    счёта, не нужно там никому. Стену в итоге снесли — задача 105,
    `max_overflow=-1`, разбор в `CLAUDE.md` §6.0.6, — но функция осталась
    по причине выше у `_пауза`: держать открытую транзакцию через
    полуторасекундный счёт незачем.

    `db.close()` возвращает соединение в пул. Сессия остаётся рабочей —
    следующий запрос откроет соединение заново, — но объекты ORM
    ОТЦЕПЛЯЮТСЯ: уже прочитанные поля читаются по-прежнему, а запись
    в них до базы не доедет. Поэтому на вызывающей стороне действует
    правило: значение, нужное после, взять в переменную ДО; объект,
    который будут менять, взять из базы заново.
    """
    db.close()
    return await asyncio.to_thread(функция, *аргументы)


# ── Блокирующее в async-обработчике: только через asyncio.to_thread ──────────
#
# ПРАВИЛО: синхронный вызов, считающий дольше десятка миллисекунд, внутри
# `async def` обработчика запрещён. Уносится в поток —
# `await asyncio.to_thread(функция, аргументы)`.
#
# Причина ровно та же, что у `_пауза` выше, и это ТРЕТИЙ случай одного
# класса подряд (пул соединений — задача 22, bcrypt и остальное —
# задача 103). Пока синхронный вызов считает, event loop не исполняет
# НИЧЕГО: ни другие запросы, ни таймеры, ни отправку уже готовых ответов.
# Отказ немой — ни ошибки, ни строки в журнале, приложение просто
# перестаёт отвечать целиком, включая `/health`, по которому Fly решает,
# жива ли машина.
#
# Замер 2026-08-18 на этой машине, стоимость ОДНОГО вызова:
#
#   verify_password (bcrypt cost 12)   148.7 мс
#   hash_password                      153.2 мс
#   _upright_jpeg (JPEG 4000×3000)      87.1 мс
#   _process_avatar (3000×3000)         80.1 мс
#   httpx.Client синхронный        до таймаута: у zepp_client он 30 000 мс
#   subprocess.run git rev-parse        10.9 мс
#   запрос к SQLite через SQLAlchemy     0.1 мс  ← в поток НЕ уносится
#   commit в SQLite (WAL, synchronous=FULL)  1.6 мс  ← и он тоже
#
# Последняя строка — граница правила: сотые доли миллисекунды в поток
# уносить незачем, а вот тридцать секунд синхронного httpx кладут сайт
# целиком, и это хуже bcrypt на два порядка.
#
# Про базу отдельно (задача 105, 2026-08-20). До неё дорогими были не сами
# запросы, а два места ВОКРУГ них: очередь за соединением в пуле (до 30 с)
# и `commit` при открытом чужом чтении под journal_mode=delete (5527 мс,
# затем `database is locked`). Оба убраны настройкой движка — очередь
# выключена, журнал WAL, — и потому работа с базой в поток по-прежнему
# не уносится: уносить теперь действительно нечего. Разбор и замеры —
# `CLAUDE.md` §6.0.6.
#
# Соблюдение проверяется машиной: `py check_blocking.py` (проверка 11)
# обходит граф вызовов от каждого async-обработчика и печатает те, что
# достают до блокирующего примитива НЕ через поток. Правило, которое надо
# не забыть соблюсти, — это гарантия, что следующий обработчик его
# не получит (та же причина, по которой гейт подтверждения почты сделан
# одним middleware, §5.3).


def _login_delay_for(fails: int) -> float:
    """Прогрессивная задержка ответа. Человеку незаметна, перебору ломает
    экономику — и, в отличие от капчи, не зависит от доступности Cloudflare.

    Потолок обязателен и равен 4 с: без него это отказ в обслуживании самим
    себе — соединения копятся, а воркер один.
    """
    if fails >= 8:
        return 4.0
    if fails >= 5:
        return 2.0
    if fails >= LOGIN_CAPTCHA_AFTER:
        return 1.0
    return 0.0


def _issue_verification_token(user) -> str:
    """Генерирует свежий verification_token (24ч) и записывает в объект user. Не коммитит, не отправляет письмо."""
    vtok = generate_token()
    user.verification_token = vtok
    user.verification_token_expires = datetime.utcnow() + timedelta(hours=24)
    return vtok


def _verification_email_html(link: str) -> str:
    return f"""
<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px 24px;background:#07070f;border-radius:16px;border:1px solid rgba(255,255,255,0.08)">
  <div style="font-size:1.5rem;font-weight:800;margin-bottom:8px;color:#dde2f0">⚡ EnergyDess</div>
  <div style="color:#5a6888;font-size:0.875rem;margin-bottom:24px">Подтверждение регистрации</div>
  <p style="color:#dde2f0;line-height:1.6;margin-bottom:24px">
    Для завершения регистрации перейдите по ссылке ниже. Ссылка действует 24 часа.
  </p>
  <a href="{link}"
     style="display:inline-block;padding:13px 28px;background:linear-gradient(135deg,#7c4dff,#00d4ff);color:#fff;text-decoration:none;border-radius:10px;font-weight:700;font-size:0.95rem">
    Подтвердить email →
  </a>
  <p style="color:#2a3050;font-size:0.78rem;margin-top:24px">
    Если вы не регистрировались на EnergyDess — просто проигнорируйте это письмо.
  </p>
</div>"""


# Минимальный интервал между письмами одному пользователю. Не полноценный
# rate limiting (это BACKLOG №1), а защита от долбления кнопки «отправить ещё раз».
EMAIL_COOLDOWN_SEC = 60


def _email_cooldown_left(db, user_id: int) -> int:
    """Сколько секунд осталось ждать до следующей отправки. 0 — можно слать.

    Считается только по УСПЕШНЫМ отправкам: если предыдущая попытка провалилась,
    письма у человека нет, и держать его минуту на «письмо уже отправлено» —
    значит врать ему ровно так же, как раньше врала молчаливая регистрация.
    """
    if not user_id:
        return 0
    последнее = (db.query(EmailLog)
                 .filter(EmailLog.user_id == user_id, EmailLog.error.is_(None))
                 .order_by(EmailLog.created_at.desc())
                 .first())
    if not последнее or not последнее.created_at:
        return 0
    прошло = (datetime.utcnow() - последнее.created_at).total_seconds()
    return max(0, int(EMAIL_COOLDOWN_SEC - прошло))


def _исход_письма(ошибка: str | None) -> str:
    """Что показать на странице по результату отправки: три исхода, не два.

    Третий появился вместе с суточным запасом адреса (задача 22). Свалить
    его в `failed` значило бы говорить «проблема на нашей стороне, попробуйте
    через несколько минут» там, где проблем нет и через несколько минут
    ничего не изменится.
    """
    if not ошибка:
        return "sent"
    return "limit" if str(ошибка).startswith("limit:") else "failed"


def _last_email_failed(db, user_id: int) -> str | None:
    """Чем кончилась ПОСЛЕДНЯЯ попытка отправки: 'failed', 'limit' или None.

    Нужно, чтобы /verify-pending сразу после регистрации не утверждал «мы
    отправили письмо», если не отправили. Возвращает строку, а не флаг:
    отказ по суточному запасу адреса — не сбой канала, и показывать на него
    «проблема на нашей стороне, попробуйте через несколько минут» значит
    врать. Раньше исходов было два, стало три (задача 22).
    """
    if not user_id:
        return None
    последнее = (db.query(EmailLog)
                 .filter(EmailLog.user_id == user_id)
                 .order_by(EmailLog.created_at.desc())
                 .first())
    if not последнее or not последнее.error:
        return None
    return _исход_письма(последнее.error)


def _verification_email_text(link: str) -> str:
    """Текстовая версия письма подтверждения.

    Письмо без plain-text альтернативы — заметный минус в спам-оценке: мало
    текста плюс одна яркая кнопка-ссылка складываются для фильтра в узнаваемый
    фишинговый силуэт. Ссылка здесь в явном виде, чтобы её можно было
    скопировать руками, если кнопка в HTML не сработала.
    """
    return f"""EnergyDess — подтверждение регистрации

Для завершения регистрации откройте ссылку (действует 24 часа):

{link}

Если вы не регистрировались на EnergyDess — просто проигнорируйте это письмо.
"""


def _reset_email_text(link: str) -> str:
    return f"""EnergyDess — сброс пароля

Для установки нового пароля откройте ссылку (действует 1 час):

{link}

Если вы не запрашивали сброс пароля — просто проигнорируйте это письмо.
"""


async def send_email(to: str, subject: str, html: str, text: str = None,
                     db=None, user_id: int = None, kind: str = "verify",
                     учитывать_лимит: bool = True) -> str | None:
    """Отправляет письмо через Resend. Возвращает None при успехе, иначе строку
    «<код>: <детали>».

    Раньше здесь было три слепые зоны: тихий return без ключа, непрочитанный
    ответ (не-200 не обнаруживался вообще, даже без исключения) и голый
    except Exception. Канал мог отвалиться целиком, а регистрация продолжала
    показывать «письмо отправлено».

    `учитывать_лимит=False` — только для письма-предупреждения о переборе
    (`_письмо_о_переборе`). У него свой кулдаун в шесть часов, а тратить
    на него общий суточный запас адреса нельзя: тогда атакующий четырьмя
    предупреждениями выжигал бы владельцу возможность сбросить пароль.
    """
    resend_id = None
    error = None

    # ЗАСЛОН СТОИТ ЗДЕСЬ, А НЕ В КАЖДОМ ЭНДПОИНТЕ, и это та же причина, что
    # у гейта подтверждённой почты (§5.3): проверку, которую надо не забыть
    # дописать, следующий эндпоинт не получит, и никто этого не заметит.
    # Ключ — АДРЕС НАЗНАЧЕНИЯ, а не кука и не сессия: кука выбрасывается
    # в две секунды и защитой не является (замер: шесть повторов с одной
    # кукой дали шесть отправок за секунду).
    if учитывать_лимит and db is not None:
        ключ_почты = _ключ_почты(to)
        if _попыток(db, ключ_почты, "mail", MAIL_WINDOW_SEC, "sent") >= MAIL_MAX_PER_ADDR:
            # Префикс `limit:` читается вызывающим: отказ по лимиту — не сбой
            # канала, и говорить человеку «проблема на нашей стороне» здесь
            # было бы неправдой
            error = (f"limit: за сутки на этот адрес уже ушло "
                     f"{MAIL_MAX_PER_ADDR} писем")
            print(f"[email] отказ по лимиту адреса ({kind}): "
                  f"{MAIL_MAX_PER_ADDR}+ писем за сутки")

    if error:
        pass
    elif not RESEND_API_KEY:
        # Не норма, а ошибка конфигурации: письма не уходят вообще
        error = "no_key: RESEND_API_KEY не задан — письма не отправляются"
    else:
        письмо = {
            "from": "EnergyDess <noreply@energydess.ru>",
            "to": [to],
            "subject": subject,
            "html": html,
        }
        if text:
            письмо["text"] = text
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                r = await client.post(
                    RESEND_API_URL,
                    headers={
                        "Authorization": f"Bearer {RESEND_API_KEY}",
                        "Content-Type": "application/json",
                    },
                    json=письмо,
                )
            if r.status_code >= 400:
                # Протухший ключ, слетевшая верификация домена, лимит, отбитый адрес
                error = f"http_{r.status_code}: {r.text[:300]}"
            else:
                # Resend возвращает {"id": "..."} — по нему видно статус доставки
                # в их дашборде (delivered / bounced / complained)
                resend_id = (r.json() or {}).get("id")
        except httpx.TimeoutException:
            error = "timeout: Resend не ответил за 10 с"
        except httpx.HTTPError as e:
            error = f"network: {type(e).__name__}: {str(e)[:200]}"
        except ValueError as e:
            # тело ответа не разобралось как JSON — письмо, вероятно, ушло
            error = f"parse: {type(e).__name__}: {str(e)[:200]}"

    if error:
        print(f"[email] сбой отправки на {to} ({kind}): {error}")

    # Расход адреса считается ПО ПОПЫТКЕ, а не по успеху — и это не мелочь.
    # Прежний кулдаун (`_email_cooldown_left`) считался только по успешным
    # отправкам, то есть при лежащем Resend не ограничивал ничего: замер
    # на приложении с пустым ключом дал шесть отправок подряд без единой
    # паузы. Запас адреса обязан кончаться и тогда, когда письма не уходят:
    # каждая попытка — это запрос к Resend нашими руками
    if учитывать_лимит and db is not None and not str(error or "").startswith("limit:"):
        try:
            _записать_попытку(db, _ключ_почты(to), "mail", "sent")
        except SQLAlchemyError as e:
            print(f"[email] не удалось записать расход адреса: {type(e).__name__}: {e}")

    if db is not None:
        try:
            db.add(EmailLog(user_id=user_id, to_email=to, kind=kind,
                            resend_id=resend_id, error=error))
            db.commit()
        except Exception as e:
            # журнал не должен ломать сам сценарий, но молчать о нём тоже нельзя
            print(f"[email] не удалось записать EmailLog: {type(e).__name__}: {e}")
    return error


# Письмо-предупреждение владельцу. Единственное последствие счёта по аккаунту,
# кроме задержки: аккаунт не запирается ни на секунду, и владелец с верным
# паролем входит с первой попытки — иначе форма входа стала бы оружием против
# пользователя, у которого кто-то знает адрес почты.
_НАЗВАНИЕ_ПРЕДУПРЕЖДЕНИЯ = "Кто-то подбирает пароль к вашему аккаунту"


def _письмо_о_переборе_html(сколько: int) -> str:
    return f"""
<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px 24px;background:#07070f;border-radius:16px;border:1px solid rgba(255,255,255,0.08)">
  <div style="font-size:1.5rem;font-weight:800;margin-bottom:8px;color:#dde2f0">⚡ EnergyDess</div>
  <div style="color:#5a6888;font-size:0.875rem;margin-bottom:24px">Безопасность аккаунта</div>
  <p style="color:#dde2f0;line-height:1.6;margin-bottom:16px">
    За последние 15 минут в ваш аккаунт пробовали войти с неверным паролем
    {сколько} раз. Возможно, это вы — тогда просто войдите заново.
  </p>
  <p style="color:#dde2f0;line-height:1.6;margin-bottom:24px">
    Если это не вы — смените пароль. Аккаунт мы не блокируем: иначе любой,
    кто знает ваш адрес, мог бы закрыть вам вход когда угодно.
  </p>
  <a href="{BASE_URL}/forgot-password"
     style="display:inline-block;padding:13px 28px;background:linear-gradient(135deg,#7c4dff,#00d4ff);color:#fff;text-decoration:none;border-radius:10px;font-weight:700;font-size:0.95rem">
    Сменить пароль →
  </a>
  <p style="color:#2a3050;font-size:0.78rem;margin-top:24px">
    Письмо отправлено автоматически. Чаще чем раз в 6 часов мы его не шлём.
  </p>
</div>"""


def _письмо_о_переборе_text(сколько: int) -> str:
    return f"""EnergyDess — безопасность аккаунта

За последние 15 минут в ваш аккаунт пробовали войти с неверным паролем
{сколько} раз.

Если это были вы — просто войдите заново. Если нет — смените пароль:
{BASE_URL}/forgot-password

Аккаунт мы не блокируем: иначе любой, кто знает ваш адрес, мог бы
закрыть вам вход когда угодно.
"""


async def _письмо_о_переборе(db, user, сколько: int) -> None:
    """Шлёт предупреждение владельцу, но не чаще NOTICE_COOLDOWN_SEC.

    Кулдаун обязателен и держится на том же журнале: без него десять неудач
    подряд дали бы десять писем, а перебор длиной в сутки — сотни. Ключ
    у кулдауна свой (`вид='notice'`), чтобы предупреждения не тратили общий
    суточный запас адреса.
    """
    ключ = _ключ_почты(user.email)
    if _попыток(db, ключ, "notice", NOTICE_COOLDOWN_SEC, "sent"):
        return
    _записать_попытку(db, ключ, "notice", "sent")
    print(f"[login] {сколько} неудач по одному аккаунту — владельцу отправлено предупреждение")
    await send_email(to=user.email, subject=_НАЗВАНИЕ_ПРЕДУПРЕЖДЕНИЯ,
                     html=_письмо_о_переборе_html(сколько),
                     text=_письмо_о_переборе_text(сколько),
                     db=db, user_id=user.id, kind="notice",
                     учитывать_лимит=False)


def _render_404(request: Request):
    """404 с общей шапкой.

    Пользователя приходится доставать вручную: в обработчики исключений
    FastAPI зависимости не внедряет, а без user шапка рисует гостевой
    вариант — залогиненный видел бы «Войти» на странице ошибки.
    Сессия закрывается ПОСЛЕ рендера: объект user отвязался бы от сессии,
    и шаблон не смог бы прочитать его поля."""
    db = SessionLocal()
    try:
        user = get_current_user(access_token=request.cookies.get("access_token"), db=db)
        return templates.TemplateResponse(request=request, name="404.html",
                                          status_code=404, context={"user": user})
    finally:
        db.close()


@app.exception_handler(404)
async def not_found_handler(request: Request, exc: HTTPException):
    return _render_404(request)


@app.api_route("/health", methods=["GET", "HEAD"])
async def health():
    return JSONResponse({"status": "ok"})


@app.get("/version")
async def version():
    import subprocess
    repo_dir = os.path.dirname(os.path.abspath(__file__))
    try:
        # В поток: запуск процесса стоит ~11 мс, и платит за него чужой
        # запрос, которому до нашего git дела нет
        готово = await asyncio.to_thread(
            subprocess.run,
            ["git", "rev-parse", "--short", "HEAD"],
            cwd=repo_dir, capture_output=True, text=True, check=True,
        )
        commit = готово.stdout.strip()
    except Exception:
        commit = "unknown"
    return JSONResponse({"commit": commit})


@app.post("/deploy-hook")
async def deploy_hook(request: Request):
    token = request.headers.get("X-Deploy-Token", "")
    expected = os.getenv("DEPLOY_SECRET", "")
    if not expected or token != expected:
        return JSONResponse({"error": "Forbidden"}, status_code=403)
    import subprocess
    # git pull с повторами — у VPS периодически рвётся связь с GitHub
    script = (
        "sleep 2 && cd /var/www/energydess && "
        "(git pull origin main || (sleep 5 && git pull origin main) || (sleep 15 && git pull origin main)) && "
        "systemctl restart energydess"
    )
    log = open("/var/log/energydess-deploy.log", "a")
    subprocess.Popen(["bash", "-c", script], stdout=log, stderr=subprocess.STDOUT)
    return JSONResponse({"ok": True})


def _import_exercises_if_empty():
    """Первичное наполнение справочника из exercises_seed.json — один раз
    при первом старте, если таблица пустая (напр. свежий volume на проде).
    Идемпотентно: на непустой таблице ничего не делает.

    Это СЕМЯ, а не бэкап: 873 упражнения с переводом и кластеризацией
    оборудования, но БЕЗ youtube_id — их проставил многодневный импорт уже
    после наполнения. Снимок справочника вместе с видео лежит отдельно,
    в backups/exercises/, и накатывается через dump_exercises.py --restore.
    Файл назывался exercises_data.json и был переименован ровно затем,
    чтобы эти две вещи нельзя было перепутать."""
    db = SessionLocal()
    try:
        if db.query(Exercise).first():
            return
        path = os.path.join(os.path.dirname(__file__), "exercises_seed.json")
        if not os.path.exists(path):
            return
        with open(path, encoding="utf-8") as f:
            data = _json.load(f)
        for row in data:
            db.add(Exercise(
                id=row["id"], name=row["name"], name_ru=row["name_ru"],
                force=row["force"], level=row["level"], mechanic=row["mechanic"],
                equipment=row["equipment"], equipment_cluster=row["equipment_cluster"],
                primary_muscles=row["primary_muscles"], secondary_muscles=row["secondary_muscles"],
                instructions=row["instructions"], instructions_ru=row["instructions_ru"],
                category=row["category"], images=row["images"],
            ))
        db.commit()
        print(f"Импортировано упражнений: {len(data)}")
    finally:
        db.close()


@app.on_event("startup")
def startup():
    init_db()
    migrate_db()
    _import_exercises_if_empty()


