@app.get("/")
async def index(request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not user:
        return templates.TemplateResponse(request=request, name="landing.html")

    tools_with_access = [
        {**t, "has_access": user_has_access(user, t["id"], db)}
        for t in TOOLS
    ]
    return templates.TemplateResponse(request=request, name="index.html",
                                      context={"user": user, "tools": tools_with_access})


# ── Регистрация ───────────────────────────────────────────────────────────────

@app.get("/register")
async def register_page(request: Request, user=Depends(get_current_user)):
    if user:
        return RedirectResponse("/", status_code=302)
    return templates.TemplateResponse(request=request, name="register.html",
                                      context={"error": None, "turnstile_site_key": TURNSTILE_SITE_KEY})


@app.post("/register")
async def register(
    request: Request,
    email: str = Form(...),
    password: str = Form(...),
    password2: str = Form(...),
    turnstile_token: str = Form(default="", alias="cf-turnstile-response"),
    db: Session = Depends(get_db),
):
    email = email.strip().lower()
    ctx = {"email": email, "turnstile_site_key": TURNSTILE_SITE_KEY}

    if not await _verify_turnstile(turnstile_token, request.client.host if request.client else None):
        return templates.TemplateResponse(request=request, name="register.html", status_code=400,
                                          context={**ctx, "error": "Не удалось подтвердить, что вы не робот"})
    if password != password2:
        return templates.TemplateResponse(request=request, name="register.html",
                                          context={**ctx, "error": "Пароли не совпадают"})
    if len(password) < MIN_PASSWORD_LEN:
        return templates.TemplateResponse(
            request=request, name="register.html",
            context={**ctx, "error": f"Пароль минимум {MIN_PASSWORD_LEN} символов"})
    существующий = db.query(User).filter(User.email == email).first()
    if существующий:
        # Подтверждённый адрес — отказ, это нормально
        if существующий.is_verified is not False:
            return templates.TemplateResponse(request=request, name="register.html",
                                              context={**ctx, "error": "Email уже зарегистрирован"})
        # Неподтверждённый — тупик: письма нет (могло уйти в спам), повторить
        # неоткуда, перерегистрироваться нельзя. Вместо отказа шлём подтверждение
        # заново. Пароль не меняем и форму заново проходить не заставляем:
        # человек уже её заполнял, а сменить чужой пароль так было бы нельзя.
        осталось = _email_cooldown_left(db, существующий.id)
        # ?sent / ?too_soon задают текст сообщения: после регистрации письмо
        # ушло впервые и слово «уже» там неуместно, а при попытке повторить
        # слишком рано — наоборот, на своём месте
        адрес = "/verify-pending?too_soon=1" if осталось else "/verify-pending?sent=1"
        ответ = RedirectResponse(адрес, status_code=302)
        ответ.set_cookie("pending_verify", create_token(существующий.id, _pwd_stamp(существующий)),
                         httponly=True, max_age=60 * 30, samesite="lax")
        if осталось:
            # Кулдаун соблюдаем и здесь, иначе форма регистрации станет
            # способом его обойти и слать письма без ограничений
            return ответ
        vtok = _issue_verification_token(существующий)
        db.commit()
        ссылка = f"{BASE_URL}/verify/{vtok}"
        await send_email(to=email, subject="Подтвердите регистрацию на EnergyDess",
                         html=_verification_email_html(ссылка),
                         text=_verification_email_text(ссылка),
                         db=db, user_id=существующий.id, kind="resend")
        return ответ

    is_first = db.query(User).count() == 0
    # bcrypt считает ~153 мс и держит event loop — в поток (см. правило
    # «Блокирующее в async-обработчике» рядом с _пауза)
    хеш = await _в_потоке(db, hash_password, password)
    user = User(
        email=email,
        password_hash=хеш,
        is_admin=is_first,
        is_verified=True if is_first else False,
    )
    if not is_first:
        vtok = _issue_verification_token(user)
    db.add(user)
    db.commit()
    db.refresh(user)

    resume = Resume(user_id=user.id, resume_text="")
    db.add(resume)
    db.commit()

    if not is_first:
        link = f"{BASE_URL}/verify/{vtok}"
        await send_email(to=email, subject="Подтвердите регистрацию на EnergyDess",
                         html=_verification_email_html(link),
                         text=_verification_email_text(link),
                         db=db, user_id=user.id, kind="verify")
        response = RedirectResponse("/verify-pending?sent=1", status_code=302)
        # Короткоживущая метка, чтобы на /verify-pending работала кнопка повтора:
        # сессии там ещё нет (вход не выполняется), а открытая форма с вводом
        # email превратила бы страницу в рассылку писем на любой адрес
        response.set_cookie("pending_verify", create_token(user.id, _pwd_stamp(user)),
                            httponly=True, max_age=60 * 30, samesite="lax")
        return response

    token = create_token(user.id, _pwd_stamp(user))
    response = RedirectResponse("/profile", status_code=302)
    response.set_cookie("access_token", token, httponly=True, max_age=60 * 60 * 24 * 30, samesite="lax")
    return response


# ── Вход ──────────────────────────────────────────────────────────────────────

@app.get("/login")
async def login_page(request: Request, user=Depends(get_current_user),
                     verified: str = None, error: str = None, next: str = None,
                     db: Session = Depends(get_db)):
    if user:
        return RedirectResponse(_safe_next(next), status_code=302)
    # Капчу показываем уже при открытии формы, если с этого IP было
    # достаточно неудач: иначе человек заполнит поля, отправит и только
    # тогда узнает, что нужна ещё и проверка
    ip = _client_ip(request)
    нужна_капча = (not _ratelimit_disabled(ip, "GET /login")
                   and _попыток(db, _ключ_ip(ip), "login", LOGIN_WINDOW_SEC) >= LOGIN_CAPTCHA_AFTER
                   and bool(TURNSTILE_SITE_KEY))
    msg = None
    if verified:
        msg = "✓ Email подтверждён — теперь можно войти"
    elif error == "bad_token":
        msg = "Неверная ссылка подтверждения"
    elif error == "expired_token":
        msg = "Ссылка устарела — войдите в аккаунт, там можно отправить новую ссылку"
    return templates.TemplateResponse(
        request=request, name="login.html",
        context={"error": None, "info": msg, "next": _safe_next(next),
                 "turnstile_site_key": TURNSTILE_SITE_KEY if нужна_капча else None})


@app.post("/login")
async def login(
    request: Request,
    email: str = Form(...),
    password: str = Form(...),
    turnstile_token: str = Form(default="", alias="cf-turnstile-response"),
    next: str = Form(default=""),
    db: Session = Depends(get_db),
):
    email = email.strip().lower()
    ip = _client_ip(request)
    # Ключей ДВА, и последствия у них разные. По адресу подключения (для IPv6
    # это префикс /64, а не отдельный адрес) — задержка и потолок попыток.
    # По введённому адресу почты — задержка и письмо владельцу, но НИКАКОЙ
    # блокировки: иначе любой, зная чужую почту, запирал бы чужой вход.
    # В логи пишем именно ключ адреса — иначе при разборе инцидента будет
    # путаница, по чему на самом деле сработал лимит
    ключ = _ключ_ip(ip)
    ключ_акк = _ключ_аккаунта(email)
    защита = not _ratelimit_disabled(ip, "POST /login")
    неудач = _попыток(db, ключ, "login", LOGIN_WINDOW_SEC) if защита else 0
    неудач_акк = _попыток(db, ключ_акк, "login", LOGIN_WINDOW_SEC) if защита else 0
    # Задержка берётся БОЛЬШАЯ из двух, а не сумма: потолок 4 с объявлен
    # потолком, и складывать ключи значило бы тихо сделать его восемью
    пауза = _login_delay_for(max(неудач, неудач_акк))
    # КАПЧА ВКЛЮЧАЕТСЯ ТОЛЬКО ПО СЧЁТУ АДРЕСА ПОДКЛЮЧЕНИЯ, и это решение,
    # а не недосмотр. Пробовали иначе — включать её и по счёту аккаунта,
    # чтобы ротация адресов не обходила проверку даром. Замер 2026-08-18
    # показал, во что это выливается вместе с fail-closed из ветки ниже:
    # десять неудачных попыток по чужому аккаунту, и ВЛАДЕЛЕЦ с верного
    # пароля и чистого адреса получает `капча-отказ 400`. То есть посторонний
    # человек, знающий только адрес почты, запирает чужой вход — ровно то,
    # что в этом файле запрещено абзацем выше и запрещено не зря.
    #
    # Цена отказа названа: перебор с ротацией адресов капчу не встречает.
    # Что его встречает — задержка по аккаунту (до 4 с на попытку), три
    # попытки на адрес до его собственной капчи, потолок 30 на адрес
    # и письмо владельцу. Это хуже, чем капча, и лучше, чем оружие против
    # пользователя.
    нужна_капча = защита and неудач >= LOGIN_CAPTCHA_AFTER and bool(TURNSTILE_SITE_KEY)

    # ── Потолок числа попыток С ЭТОГО АДРЕСА ─────────────────────────────────
    # Не блокировка аккаунта: ключ здесь — адрес подключения, а не человек.
    # Окно скользящее, освобождается само; разбор, почему потолок вообще
    # нужен при наличии задержки, — у константы LOGIN_BLOCK_AFTER
    if защита and неудач >= LOGIN_BLOCK_AFTER:
        print(f"[login] {ключ}: {неудач} неудач за 15 мин — отказ, пока окно не сдвинется")
        await _пауза(db, пауза)
        return templates.TemplateResponse(
            request=request, name="login.html", status_code=429,
            context={"error": "Слишком много попыток входа с вашего адреса. "
                              "Попробуйте через 15 минут.",
                     "email": email, "next": _safe_next(next),
                     "turnstile_site_key": TURNSTILE_SITE_KEY if нужна_капча else None})

    # ── Капча после нескольких неудач: ДВЕ РАЗНЫЕ ВЕТКИ ──────────────────────
    # Различие принципиальное, и реализовано оно именно двумя ветками:
    #
    #   нет токена вовсе — ОТКАЗ. Наша форма без токена не отправляется:
    #     виджет Turnstile сам подставляет скрытое поле. Пустое поле значит,
    #     что запрос собран не браузером с нашей страницы. Прежний код
    #     пропускал такой запрос, и записанное следствие — «бот, не
    #     отправляющий поле капчи, проходит её насквозь» — было замерено
    #     живьём: POST без поля прошёл и с верным паролем дал вход;
    #
    #   Cloudflare не ответил — ПРОПУСКАЕМ. Это наша проблема, а не
    #     пользователя, и запереть владельца в собственной админке из-за
    #     чужого сбоя хуже, чем пропустить попытку, которую режет потолок.
    #
    # Цена первой ветки названа: человек с заблокированным Cloudflare
    # (расширение, корпоративный фильтр) после трёх опечаток войти не сможет,
    # пока не сдвинется окно. Аварийный выход на этот случай — файл
    # /data/ratelimit_off, он снимает защиту целиком (§8.1).
    if нужна_капча:
        if not turnstile_token:
            print(f"[login] {ключ}: поле капчи не прислано — отказ (fail-closed)")
            # ОТКАЗ НЕ ЗАСЧИТЫВАЕТСЯ НИ В ОДИН СЧЁТ, и это важнее, чем
            # кажется. Счёт отвечает на вопрос «сколько паролей отсюда
            # перебрали»; запрос, не дошедший до проверки пароля, — не
            # перебор. А главное, у человека, которому виджет не загрузился
            # (блокировщик, корпоративный фильтр, страна), должен быть
            # выход без нашего участия: окно 15 минут истекает само, если
            # он перестанет жать. Считай мы эти отказы, каждое нажатие
            # продлевало бы окно, и выхода не было бы вовсе.
            #
            # Цена: бот без токена может стучаться бесконечно, не набирая
            # счёт. Он при этом не пробует НИ ОДНОГО пароля — до bcrypt
            # дело не доходит, тратится только пауза
            await _пауза(db, пауза)
            return templates.TemplateResponse(
                request=request, name="login.html", status_code=400,
                context={"error": "Проверка «вы не робот» не прошла. Она "
                                  "работает через Cloudflare — если у вас "
                                  "включён блокировщик или VPN, отключите его "
                                  "для этой страницы и обновите её. Если "
                                  "проверка не появляется совсем, подождите "
                                  "15 минут: она включается после нескольких "
                                  "неудачных попыток и снимается сама.",
                         "email": email, "next": _safe_next(next),
                         "turnstile_site_key": TURNSTILE_SITE_KEY})
        прошла, доступен, причина = await _turnstile_check(turnstile_token, ip)
        if not доступен:
            # ПЕЧАТАЕТСЯ КАЖДЫЙ РАЗ, повтор не глушится намеренно: длительная
            # недоступность обязана выглядеть в логе потоком, а не одной
            # строкой. Одна строка читается как «разовый сбой» ровно тогда,
            # когда fail-open работает уже сутки и пропускает всё подряд
            print(f"[login] {ключ}: КАПЧА НЕ ПРОВЕРЕНА — Cloudflare недоступен "
                  f"({причина}); вход пропущен (fail-open)")
        elif not прошла:
            print(f"[login] {ключ}: капча не пройдена — отказ")
            await _пауза(db, пауза)
            return templates.TemplateResponse(
                request=request, name="login.html", status_code=400,
                context={"error": "Не удалось подтвердить, что вы не робот",
                         "email": email, "next": _safe_next(next),
                         "turnstile_site_key": TURNSTILE_SITE_KEY})

    user = db.query(User).filter(User.email == email).first()

    # Хеш читается ДО `_в_потоке`: после освобождения соединения объект
    # отцеплен от сессии, и обращение к неподгруженному полю полезло бы
    # в базу заново
    хеш = user.password_hash if user else None
    if not user or not await _в_потоке(db, verify_password, password, хеш):
        if защита:
            _записать_попытку(db, ключ, "login", "fail")
            _записать_попытку(db, ключ_акк, "login", "fail")
            неудач += 1
            неудач_акк += 1
            if неудач == LOGIN_CAPTCHA_AFTER:
                print(f"[login] {ключ}: {неудач} неудачи за 15 мин — включена капча")
            elif неудач == LOGIN_BLOCK_AFTER:
                print(f"[login] {ключ}: {неудач} неудач за 15 мин — дальше отказ")
            # Письмо владельцу — единственное последствие счёта ПО АККАУНТУ,
            # кроме задержки. Аккаунт при этом остаётся рабочим: владелец
            # с верным паролем входит с первой попытки
            if user is not None and неудач_акк >= NOTICE_AFTER:
                await _письмо_о_переборе(db, user, неудач_акк)
            # Только через _пауза: time.sleep остановил бы весь event loop,
            # а голый asyncio.sleep держал бы соединение к базе (см. _пауза)
            await _пауза(db, _login_delay_for(max(неудач, неудач_акк)))
        показать_капчу = защита and неудач >= LOGIN_CAPTCHA_AFTER and bool(TURNSTILE_SITE_KEY)
        return templates.TemplateResponse(
            request=request, name="login.html",
            context={"error": "Неверный email или пароль", "email": email,
                     "next": _safe_next(next),
                     "turnstile_site_key": TURNSTILE_SITE_KEY if показать_капчу else None})

    # Успешный вход обнуляет ОБА счёта: владелец доказал, что он владелец
    _сбросить_попытки(db, ключ, ключ_акк)
    _записать_попытку(db, ключ, "login", "ok")

    # is_verified=False НЕ блокирует вход — пользователь логинится как обычно,
    # блокировка происходит на уровне конкретного инструмента (см. _verification_gate),
    # где есть кнопка повторной отправки письма (/resend-verification).
    token = create_token(user.id, _pwd_stamp(user))
    # Возврат туда, откуда пришли (витрина инструмента), а не на главную
    response = RedirectResponse(_safe_next(next), status_code=302)
    response.set_cookie("access_token", token, httponly=True, max_age=60 * 60 * 24 * 30, samesite="lax")
    return response


# ── Выход ─────────────────────────────────────────────────────────────────────

@app.get("/logout")
async def logout():
    response = RedirectResponse("/", status_code=302)
    response.delete_cookie("access_token")
    return response


# ── Email verification ────────────────────────────────────────────────────────

def _pending_user(pending_verify: str, db: Session):
    """Пользователь из короткоживущей куки, выданной при регистрации.
    Только неподтверждённый: для подтверждённого повторная отправка бессмысленна."""
    uid = decode_token_user_id(pending_verify)
    if not uid:
        return None
    u = db.query(User).filter(User.id == uid).first()
    return u if (u and u.is_verified is False) else None


@app.get("/verify-pending")
async def verify_pending(request: Request, pending_verify: str = Cookie(default=None),
                         sent: str = None, too_soon: str = None,
                         db: Session = Depends(get_db)):
    """Страница «проверьте почту».

    Состояние кнопки задаёт только cooldown — он считается по журналу отправок
    во ВСЕХ ветках, чтобы кнопка не предлагала действие, которое упрётся в отказ.
    Текст сообщения задаёт notice и от состояния кнопки не зависит: сразу после
    регистрации письмо отправлено впервые, и слово «уже» там читалось бы как
    «вы здесь не в первый раз» — человек пугается, что попал не туда.

    Без опознанного человека notice не выставляется вовсе. Он приходит из адреса
    (?sent=1), а адрес — не факт об этом человеке: кука живёт 30 минут, и по
    сохранённой ссылке страница уверенно писала «Письмо отправлено на None».
    Раз сказать нечего — шаблон покажет ветку «мы вас не узнаём».
    """
    u = _pending_user(pending_verify, db)
    notice = None
    if u:
        неудача = _last_email_failed(db, u.id)
        if неудача:
            notice = неудача
        elif too_soon:
            notice = "too_soon"
        elif sent:
            notice = "sent"
    return templates.TemplateResponse(request=request, name="verify_pending.html",
                                      context={"can_resend": bool(u), "email": u.email if u else None,
                                               "notice": notice,
                                               "cooldown": _email_cooldown_left(db, u.id) if u else 0})


@app.post("/verify-pending/resend")
async def verify_pending_resend(request: Request, pending_verify: str = Cookie(default=None),
                                db: Session = Depends(get_db)):
    """Повтор отправки сразу после регистрации, когда сессии ещё нет.
    Личность подтверждается кукой из /register — по email кого угодно письмо
    отправить нельзя, иначе форма стала бы инструментом рассылки на чужие ящики."""
    u = _pending_user(pending_verify, db)
    if not u:
        return RedirectResponse("/login", status_code=302)

    ctx = {"can_resend": True, "email": u.email}
    осталось = _email_cooldown_left(db, u.id)
    if осталось:
        return templates.TemplateResponse(request=request, name="verify_pending.html",
                                          context={**ctx, "notice": "too_soon", "cooldown": осталось})

    vtok = _issue_verification_token(u)
    db.commit()
    ссылка = f"{BASE_URL}/verify/{vtok}"
    ошибка = await send_email(to=u.email, subject="Подтвердите регистрацию на EnergyDess",
                              html=_verification_email_html(ссылка),
                              text=_verification_email_text(ссылка),
                              db=db, user_id=u.id, kind="resend")
    # Кулдаун пересчитывается ПОСЛЕ отправки: письмо только что ушло, значит
    # кнопка должна выключиться сразу, а не оставаться активной до первого
    # бесполезного нажатия. При сбое отправки кулдауна нет — повторить можно сразу.
    #
    # `limit` отделён от `failed` намеренно: суточный запас адреса кончился —
    # это не «проблема на нашей стороне», и обещать «попробуйте через
    # несколько минут» было бы неправдой. Здесь личность подтверждена кукой,
    # значит можно говорить прямо — скрывать не от кого
    return templates.TemplateResponse(request=request, name="verify_pending.html",
                                      context={**ctx,
                                               "notice": _исход_письма(ошибка),
                                               "cooldown": _email_cooldown_left(db, u.id)})


@app.get("/verify/{token}")
async def verify_email(token: str, db: Session = Depends(get_db)):
    user = db.query(User).filter(User.verification_token == token).first()
    if not user:
        return RedirectResponse("/login?error=bad_token", status_code=302)
    if user.verification_token_expires and user.verification_token_expires < datetime.utcnow():
        return RedirectResponse("/login?error=expired_token", status_code=302)
    user.is_verified = True
    user.verification_token = None
    user.verification_token_expires = None
    db.commit()
    return RedirectResponse("/login?verified=1", status_code=302)


@app.post("/resend-verification")
async def resend_verification(request: Request, tool_name: str = Form(default=""),
                              user=Depends(get_current_user), db: Session = Depends(get_db)):
    """Повторная отправка письма подтверждения — вызывается с плашки verify_required.html,
    когда пользователь уже залогинен, но is_verified=False (в отличие от resend через /login,
    здесь пароль второй раз вводить не нужно — сессия уже аутентифицирована)."""
    if not user:
        return RedirectResponse("/login", status_code=302)
    if user.is_verified is not False:
        return RedirectResponse("/", status_code=302)

    ctx = {"user": user, "tool_name": tool_name or "инструменту"}

    # Кулдаун: кнопку можно жать сколько угодно, а письма уходят реальные
    осталось = _email_cooldown_left(db, user.id)
    if осталось:
        return templates.TemplateResponse(request=request, name="verify_required.html",
                                          context={**ctx, "notice": "too_soon", "cooldown": осталось})

    vtok = _issue_verification_token(user)
    db.commit()
    link = f"{BASE_URL}/verify/{vtok}"
    ошибка = await send_email(to=user.email, subject="Подтвердите регистрацию на EnergyDess",
                              html=_verification_email_html(link),
                              text=_verification_email_text(link),
                              db=db, user_id=user.id, kind="resend")
    # Кулдаун пересчитывается после отправки — кнопка выключается сразу
    return templates.TemplateResponse(request=request, name="verify_required.html",
                                      context={**ctx,
                                               "notice": _исход_письма(ошибка),
                                               "cooldown": _email_cooldown_left(db, user.id)})


# ── Смена email: подтверждение НА НОВОМ адресе ────────────────────────────────
#
# BACKLOG №3. До 2026-08-20 в профиле стояла модалка-заглушка с надписью
# «эндпоинт ещё не реализован» — то есть кнопка была, а функции не было.
#
# ГЛАВНОЕ ПРАВИЛО: `users.email` меняется ТОЛЬКО после перехода по ссылке,
# пришедшей НА НОВЫЙ адрес. До этого новый адрес лежит в `pending_email`
# и не участвует ни в чём: вход, восстановление пароля и все письма идут
# на старый. Смена, начатая посторонним из угнанной сессии, не отнимает
# у владельца ни входа, ни возможности сбросить пароль.
#
# Обратная сторона того же правила — письмо НА СТАРЫЙ адрес о том, что
# смена начата. Оно и есть защита от угона: владелец ящика узнаёт о попытке
# в ту же минуту, даже если сессию увели.
#
# СРОК ССЫЛКИ — ДВА ЧАСА, И ЭТО ВЫБОР МЕЖДУ ДВУМЯ СОСЕДЯМИ. У письма
# регистрации срок 24 часа: там человек может подтвердить почту вечером
# и это нормально. У сброса пароля — 1 час: там ссылка равна доступу
# к аккаунту. Смена адреса ближе ко второму: живая ссылка — это
# незавершённый перенос аккаунта в чужой ящик. Но в отличие от сброса
# её открывают в ДРУГОМ почтовом ящике, куда ещё надо войти, и час
# на это местами мало. Два часа — верхняя граница «человек сидит
# за этим же компьютером».
EMAIL_CHANGE_TTL_HOURS = int(os.getenv("EMAIL_CHANGE_TTL_HOURS", "2"))

# Кулдаун письма-уведомления на СТАРЫЙ адрес. Свой, а не общий суточный
# запас адреса, и причина ровно та же, что у `_письмо_о_переборе`: запас
# в 8 писем на адрес — это ресурс ВЛАДЕЛЬЦА, из которого он берёт письмо
# сброса пароля. Сжечь его уведомлениями значило бы отнять у него
# единственный способ вернуть аккаунт.
EMAIL_CHANGE_NOTICE_COOLDOWN_SEC = int(
    os.getenv("EMAIL_CHANGE_NOTICE_COOLDOWN_SEC", str(30 * 60)))

# Простая проверка формы. Не RFC 5322 и не претендует: единственная
# настоящая проверка адреса — это письмо, которое по нему дошло,
# а здесь отсекается явный мусор до отправки.
_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$")


def _почта_годна(адрес: str) -> bool:
    return bool(адрес) and len(адрес) <= 254 and bool(_EMAIL_RE.match(адрес))


