@app.get("/admin/users")
async def admin_users_page(request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return RedirectResponse("/", status_code=302)

    users = db.query(User).filter(User.id != user.id).order_by(User.created_at).all()
    accesses = db.query(ToolAccess).all()
    access_set = {(a.user_id, a.tool_id) for a in accesses}

    users_data = []
    for u in users:
        users_data.append({
            "id": u.id,
            "email": u.email,
            "created_at": u.created_at,
            "tools": {t["id"]: (u.id, t["id"]) in access_set for t in TOOLS},
        })

    # ЧИСЛА ЧИПОВ СЧИТАЕТ СЕРВЕР, а не разметка. Причина не в удобстве:
    # чип отбора обещает, сколько строк он покажет, и посчитанное на клиенте
    # число совпадало бы с выдачей только пока обе стороны считают одинаково.
    # Разойдясь, они дали бы чип «С доступом 3», открывающий четыре строки, —
    # и признака ошибки не было бы никакого.
    с_доступом = sum(1 for u in users_data if any(u["tools"].values()))
    отбор = [{"id": "all",  "label": "Все",          "n": len(users_data)},
             {"id": "yes",  "label": "С доступом",   "n": с_доступом},
             {"id": "no",   "label": "Без доступа",  "n": len(users_data) - с_доступом}]

    # СЧЁТЧИК ОБРАЩЕНИЙ К СПРАВОЧНИКУ (BACKLOG №201, E.1).
    #
    # ЗДЕСЬ, А НЕ НА СВОЁМ ЭКРАНЕ, и это выбор из плохих: дашборд
    # админки удалён решением владельца (задача 147), разделов
    # осталось четыре, и ни один не про аптечку. «Пользователи» —
    # то, куда ведёт `/admin`, то есть единственная страница,
    # которую администратор открывает всегда.
    ref_день, ref_месяц, ref_осталось = _реф_остаток()
    return templates.TemplateResponse(request=request, name="admin_users.html",
                                      context={"user": user, "users": users_data,
                                               "tools": TOOLS, "отбор": отбор,
                                               "ref_день": ref_день,
                                               "ref_месяц": ref_месяц,
                                               "ref_предел": REF_MONTH_CAP,
                                               "ref_осталось": ref_осталось})


@app.get("/admin/products")
async def admin_products_page(request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return RedirectResponse("/", status_code=302)

    # Все продукты, добавленные пользователями в личную базу (CustomFood) —
    # для модерации/правки админом
    all_users = {u.id: u.email for u in db.query(User).all()}
    foods = db.query(CustomFood).order_by(CustomFood.created_at.desc()).all()
    foods_data = [{
        "id": f.id,
        "email": all_users.get(f.user_id, "—"),
        "name": f.name,
        "brand": f.brand or "",
        "barcode": f.barcode or "",
        "calories": f.calories_per_100g,
        "protein": f.protein_per_100g,
        "fat": f.fat_per_100g,
        "carbs": f.carbs_per_100g,
        "created_at": f.created_at,
    } for f in foods]

    # Признаки отбора выбраны по РАБОТЕ, которую тут делают: это модерация
    # чужих записей, и чинить в них нечего, кроме неполноты. Бренд и штрих-код
    # — ровно те два поля, без которых запись не склеивается с близнецом
    # из справочника (§5.0.7), то есть даёт человеку дубль в поиске.
    без_бренда = sum(1 for f in foods_data if not (f["brand"] or "").strip())
    без_кода = sum(1 for f in foods_data if not (f["barcode"] or "").strip())
    отбор = [{"id": "all",     "label": "Все",             "n": len(foods_data)},
             {"id": "nobrand", "label": "Без бренда",      "n": без_бренда},
             {"id": "nocode",  "label": "Без штрих-кода",  "n": без_кода}]

    return templates.TemplateResponse(request=request, name="admin_products.html",
                                      context={"user": user, "foods": foods_data,
                                               "отбор": отбор})


@app.get("/admin/exercises")
async def admin_exercises_page(request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return RedirectResponse("/", status_code=302)

    exercises = db.query(Exercise).order_by(Exercise.name_ru).all()
    exercises_data = []
    status_counts = {"unchecked": 0, "approved": 0, "wrong": 0, "no_video": 0}
    for e in exercises:
        status = e.video_status or "unchecked"
        status_counts[status] = status_counts.get(status, 0) + 1
        group = None
        for m in (e.primary_muscles or []):
            if m in MUSCLE_TO_GROUP:
                group = MUSCLE_TO_GROUP[m]
                break
        exercises_data.append({
            "id": e.id,
            "name_ru": e.name_ru,
            "name_en": e.name or "",
            "muscle_group": group,
            "equipment": e.equipment,
            "level": e.level or "",
            "mechanic": e.mechanic or "",
            # ТЕКСТА ТЕХНИКИ ЗДЕСЬ НЕТ — только признак. BACKLOG №159.
            # Инструкции занимали 79.7% этого списка (0.92 МБ из 1.15),
            # а на экране их не видно: блок закрыт, пока не нажали
            # «Показать технику». Текст дотягивается по требованию —
            # `/admin/api/exercise/{id}/instructions`.
            "has_instructions": bool(e.instructions_ru),
            "youtube_id": e.youtube_id or "",
            "video_status": status,
        })

    # Порядок чипов — порядок работы: сперва «сколько всего», потом «что
    # ещё не тронуто», потом исходы. «Без видео» стоит последним и несёт
    # то самое число, ради которого на удалённом дашборде была отдельная
    # ссылка-действие (BACKLOG №147).
    отбор = [{"id": "all",       "label": "Все",           "n": len(exercises_data)},
             {"id": "unchecked", "label": "Не проверено",  "n": status_counts["unchecked"]},
             {"id": "approved",  "label": "Одобрено",      "n": status_counts["approved"]},
             {"id": "wrong",     "label": "Неверное",      "n": status_counts["wrong"]},
             {"id": "no_video",  "label": "Без видео",     "n": status_counts["no_video"]}]

    return templates.TemplateResponse(request=request, name="admin_exercises.html",
                                      context={"user": user, "exercises": exercises_data,
                                               "total": len(exercises_data),
                                               "status_counts": status_counts,
                                               "отбор": отбор,
                                               "muscle_groups": MUSCLE_GROUP_LABELS_RU,
                                               "equipment_labels": EXERCISE_EQUIPMENT_LABELS_RU})


@app.post("/admin/toggle")
async def admin_toggle(
    request: Request,
    user=Depends(get_current_user),
    db: Session = Depends(get_db),
):
    if not _admin_guard(user):
        return JSONResponse({"error": "Forbidden"}, status_code=403)

    data = await request.json()
    target_user_id = int(data["user_id"])
    tool_id = data["tool_id"]

    existing = db.query(ToolAccess).filter(
        ToolAccess.user_id == target_user_id,
        ToolAccess.tool_id == tool_id
    ).first()

    if existing:
        db.delete(existing)
        db.commit()
        return JSONResponse({"access": False})
    else:
        db.add(ToolAccess(user_id=target_user_id, tool_id=tool_id))
        db.commit()
        return JSONResponse({"access": True})


@app.get("/admin/api/exercise/{exercise_id}/instructions")
async def admin_exercise_instructions(exercise_id: str, user=Depends(get_current_user),
                                      db: Session = Depends(get_db)):
    """ТЕХНИКА ОДНОГО УПРАЖНЕНИЯ — по требованию, а не со списком.

    Заведён BACKLOG №159. Список из 873 упражнений вёз текст техники
    целиком, хотя на экране он закрыт до нажатия «Показать технику»:
    0.92 МБ из 1.15 МБ данных, то есть 79.7%.

    ОТВЕТ РАЗЛИЧАЕТ ТРИ ИСХОДА, а не два: упражнения нет — 404;
    упражнение есть, техники у него нет — 200 с пустым списком.
    Свалить второе в 404 значило бы сделать «нечего показывать»
    неотличимым от «не нашли» (§6.0.1) — а кнопка «Показать технику»
    рисуется как раз по признаку `has_instructions`, и её нажатие
    на записи без техники было бы ошибкой НАШЕЙ разметки.
    """
    if not _admin_guard(user):
        return JSONResponse({"error": "Forbidden"}, status_code=403)

    у = db.query(Exercise).filter(Exercise.id == exercise_id).first()
    if not у:
        return JSONResponse({"error": "Упражнение не найдено"}, status_code=404)
    return JSONResponse({"instructions": у.instructions_ru or []})


@app.put("/admin/foods/{food_id}")
async def admin_update_food(food_id: int, request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return JSONResponse({"error": "Forbidden"}, status_code=403)

    food = db.query(CustomFood).filter(CustomFood.id == food_id).first()
    if not food:
        return JSONResponse({"error": "Не найдено"}, status_code=404)

    data = await request.json()
    food.name = (data.get("name") or food.name).strip()
    food.brand = (data.get("brand") or "").strip() or None
    food.calories_per_100g = float(data.get("calories", food.calories_per_100g))
    food.protein_per_100g = float(data.get("protein", food.protein_per_100g))
    food.fat_per_100g = float(data.get("fat", food.fat_per_100g))
    food.carbs_per_100g = float(data.get("carbs", food.carbs_per_100g))
    db.commit()
    return JSONResponse({"ok": True})


@app.delete("/admin/foods/{food_id}")
async def admin_delete_food(food_id: int, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return JSONResponse({"error": "Forbidden"}, status_code=403)

    food = db.query(CustomFood).filter(CustomFood.id == food_id).first()
    if not food:
        return JSONResponse({"error": "Не найдено"}, status_code=404)

    db.delete(food)
    db.commit()
    return JSONResponse({"ok": True})


@app.post("/admin/exercises/{exercise_id}/status")
async def admin_exercise_set_status(exercise_id: str, request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return JSONResponse({"error": "Forbidden"}, status_code=403)

    data = await request.json()
    status = data.get("status")
    if status not in ("approved", "wrong"):
        return JSONResponse({"error": "Недопустимый статус"}, status_code=400)

    ex = db.query(Exercise).filter(Exercise.id == exercise_id).first()
    if not ex:
        return JSONResponse({"error": "Не найдено"}, status_code=404)

    ex.video_status = status
    db.commit()
    return JSONResponse({"ok": True, "video_status": ex.video_status})


@app.post("/admin/exercises/{exercise_id}/replace")
async def admin_exercise_replace_video(exercise_id: str, request: Request, user=Depends(get_current_user), db: Session = Depends(get_db)):
    if not _admin_guard(user):
        return JSONResponse({"error": "Forbidden"}, status_code=403)

    ex = db.query(Exercise).filter(Exercise.id == exercise_id).first()
    if not ex:
        return JSONResponse({"error": "Не найдено"}, status_code=404)

    data = await request.json()
    url = (data.get("youtube_url") or "").strip()
    video_id = _parse_youtube_id(url)
    if not video_id:
        return JSONResponse({"error": "Ссылка должна быть с youtube.com или youtu.be"}, status_code=400)

    ex.youtube_id = video_id
    ex.video_status = "unchecked"
    ex.video_replaced_at = datetime.utcnow()
    db.commit()
    return JSONResponse({"ok": True, "youtube_id": ex.youtube_id, "video_status": ex.video_status})


# ── Enshrouded Трекер ─────────────────────────────────────────────────────────
#
# КАТАЛОГ ЖИВЁТ В БАЗЕ С 2026-08-22 (BACKLOG №137). До этого 90 сетов
# лежали JS-литералом `SETS` внутри шаблона и правились коммитом.
#
# Здесь же УМЕР `ENSHROUDED_PNG` — список id с расширением `.png`,
# который считался ОДИН раз при импорте. Он был верным решением, пока
# каталог не менялся на живом сервере; экран управления меняет ровно
# это условие, и файл, положенный им, в список не попал бы до
# перезапуска: ссылка `.jpg`, на диске `.png`, баннер схлопнут, ни
# ошибки, ни строки в журнале (задача 137, пункт 5). Расширение стало
# ПОЛЕМ сета — вопрос отпал вместе со списком.

# Категории и виды слотов НЕ переехали в базу, и это решение, а не
# недоделка. Они не содержимое, а УСТРОЙСТВО игры: пять ремесленников
# и пять мест доспеха не меняются с выходом контента, у каждого свой
# значок (Lucide у категории, встроенный SVG у слота), и править их
# экрану управления незачем — редактировать нечего. Строка в базе,
# которую нечем изменить, хуже константы: она обещает изменяемость,
# которой нет.
#
# РУССКИЕ НАЗВАНИЯ И ЗДЕСЬ НЕ ЖИВУТ. Они в `enshrouded_defs.py` —
# единственном источнике на три потребителя: этот файл, шаблон раздела
# и проверка 24. До 2026-08-23 они были ТОЛЬКО в JS-литерале шаблона,
# и экран управления показывал внутренние имена (`blacksmith`, `head`)
# в таблице, в отборе и в форме.
ENSHROUDED_CRAFTERS = _енш_опр.ИДЕНТИФИКАТОРЫ_КАТЕГОРИЙ
ENSHROUDED_SLOTS = _енш_опр.ИДЕНТИФИКАТОРЫ_СЛОТОВ


def _енш_каталог(db):
    """Каталог для страницы — В ТОМ ЖЕ ВИДЕ, в каком его читал скрипт.

    Имена полей оставлены прежними (`nameRu`, `name`, `crafter`, `lvl`,
    `pieces`, `custom`): разметка раздела уже умеет их читать, и менять
    их значило бы переписывать рисование ради переименования.
    """
    из = []
    for с in db.query(EnshroudedSet).order_by(EnshroudedSet.sort_order,
                                              EnshroudedSet.id).all():
        запись = {"id": с.id, "nameRu": с.name_ru, "name": с.name_en,
                  "crafter": с.crafter, "lvl": с.lvl,
                  "img": _енш_адрес(с)}
        if с.pieces:
            запись["pieces"] = _json.loads(с.pieces)
        if с.custom:
            запись["custom"] = _json.loads(с.custom)
        из.append(запись)
    return из


def _енш_адрес(с):
    """Адрес картинки сета — ОДИН на весь проект, и версия в нём.

    Версия (`?v=`) — восемь знаков sha256 от содержимого, ровно тот же
    приём, что у `st()` для статики (§2.2). Без неё заменённая картинка
    показывалась бы старой до суток: адрес не изменился, а `Cache-Control`
    на картинках стоит `max-age=86400`. Владелец при этом видел бы,
    что «загрузка не сработала», — немой отказ на ровном месте.
    """
    if not с.img_ext:
        return None
    хвост = f"?v={с.img_ver}" if с.img_ver else ""
    return f"/enshrouded-img/{с.id}.{с.img_ext}{хвост}"


def _енш_версия(путь):
    """Восемь знаков sha256 от содержимого файла."""
    h = hashlib.sha256()
    with open(путь, "rb") as f:
        for кусок in iter(lambda: f.read(65536), b""):
            h.update(кусок)
    return h.hexdigest()[:8]


# ИМЯ ПАРАМЕТРА ПУТИ — ЛАТИНИЦЕЙ, и это не вкус (§6.0). Первая версия
# звалась `{имя}`: обработчик при прямом вызове отдавал файл, а через
# HTTP приходил 404 — Starlette компилирует путь в регулярку с именованной
# группой, и кириллическое имя группы её ломает. Отказ немой: ни ошибки
# при импорте, ни строки в журнале, только 404 на исправном коде.
@app.get("/enshrouded-img/{name}")
async def enshrouded_image(name: str):
    """Картинка сета. Своим эндпоинтом, а не из /static, потому что
    загруженное лежит НА ТОМЕ — `static/` уезжает в образ и переживает
    деплой только в том виде, в каком туда попало (задача 137, пункт 2).

    Разрешение пути — одно на проект, `database.enshrouded_img`: том
    сильнее семени. Второй реализации нет, и проверка 24 зовёт ту же.
    """
    основа, _, ext = name.rpartition(".")
    # Имя приходит из адресной строки: пускаем только то, что сами
    # и выдаём. `..` и разделители пути сюда не пролезут по построению.
    if not основа or ext not in ("jpg", "png") or not re.fullmatch(r"[a-z0-9_]+", основа):
        return JSONResponse({"error": "Нет такой картинки"}, status_code=404)
    путь = enshrouded_img(основа, ext)
    if not путь:
        return JSONResponse({"error": "Нет такой картинки"}, status_code=404)
    return FileResponse(путь, media_type=f"image/{'png' if ext == 'png' else 'jpeg'}",
                        headers={"Cache-Control": "public, max-age=86400"})


