@app.post("/api/timezone")
async def save_timezone(request: Request, user=Depends(get_current_user),
                        db: Session = Depends(get_db)):
    if not user:
        return JSONResponse({"error": "Нужно войти"}, status_code=401)
    data = await request.json()
    tz = (data.get("timezone") or "").strip()
    # Только из своего списка: произвольная строка отсюда попала бы в
    # ZoneInfo() при расчёте дат и уронила бы страницу
    if tz not in _TZ_VALID:
        return JSONResponse({"error": "Неизвестный часовой пояс"}, status_code=400)
    user.timezone = tz
    db.commit()
    return JSONResponse({"ok": True})


# ПОЛ — ТОЛЬКО ДЛЯ ОБРАЩЕНИЯ. Значений три, и пустое среди них
# РАВНОПРАВНОЕ: «не указан» это выбор, а не пропуск. Список закрытый —
# произвольная строка отсюда попала бы в подпись кнопки.
ПОЛ_ЗНАЧЕНИЯ = {"m", "f", ""}


@app.post("/api/gender")
async def save_gender(request: Request, user=Depends(get_current_user),
                      db: Session = Depends(get_db)):
    if not user:
        return JSONResponse({"error": "Нужно войти"}, status_code=401)
    data = await request.json()
    пол = (data.get("gender") or "").strip()
    if пол not in ПОЛ_ЗНАЧЕНИЯ:
        return JSONResponse({"error": "Неизвестное значение"}, status_code=400)
    # ПУСТАЯ СТРОКА КЛАДЁТСЯ КАК NULL, а не как "": иначе в базе было бы
    # ДВА способа сказать «не указан», и `АПТ_ГЛАГОЛ_ПРИЁМА` знал бы
    # только один из них (§6.0.7).
    user.gender = пол or None
    db.commit()
    return JSONResponse({"ok": True})


